<?php
declare(strict_types=1);
require __DIR__ . '/../lib/game.php';
function ok_rule(bool $condition,string $message):void{if(!$condition){fwrite(STDERR,"FAIL: $message\n");exit(1);}echo "ok - $message\n";}
$seed=load_seed();$bankId=$seed['banks'][0]['bankId'];$levelKeys=array_column($seed['levels'],'levelKey');$categoryId=array_values(array_filter($seed['categories'],fn($c)=>$c['bankId']===$bankId&&$c['active']))[0]['categoryId'];
$runtime=empty_state();$d=create_match($runtime,['name'=>'Turnos','bankId'=>$bankId,'playerIds'=>['J1','J3'],'startingPlayerId'=>'J3','categoryIds'=>[$categoryId],'levelKeys'=>$levelKeys]);$id=$d['match']['matchId'];$d=perform_action($runtime,$id,['action'=>'draw','categoryId'=>$categoryId]);$d=perform_action($runtime,$id,['action'=>'reveal']);$d=perform_action($runtime,$id,['action'=>'result','correct'=>true]);ok_rule($d['state']['currentPlayerId']==='J3','correct answer keeps turn');$d=perform_action($runtime,$id,['action'=>'draw','categoryId'=>$categoryId]);$d=perform_action($runtime,$id,['action'=>'reveal']);$d=perform_action($runtime,$id,['action'=>'result','correct'=>false]);ok_rule($d['state']['currentPlayerId']==='J1','wrong answer rotates turn');
$runtime=empty_state();$d=create_match($runtime,['name'=>'Centro','bankId'=>$bankId,'playerIds'=>['J1','J2'],'startingPlayerId'=>'J1','categoryIds'=>[$categoryId],'levelKeys'=>$levelKeys]);$id=$d['match']['matchId'];$d=perform_action($runtime,$id,['action'=>'draw','categoryId'=>$categoryId,'quesitoAttempt'=>true]);$d=perform_action($runtime,$id,['action'=>'reveal']);$d=perform_action($runtime,$id,['action'=>'result','correct'=>true]);ok_rule($d['state']['status']==='open','all quesitos do not auto-close match');ok_rule($d['marker'][0]['hasAllQuesitos']===true,'marker reports all quesitos');$d=perform_action($runtime,$id,['action'=>'center_reached']);ok_rule($d['marker'][0]['atCenter']===true,'center arrival is persisted');$d=perform_action($runtime,$id,['action'=>'draw','categoryId'=>$categoryId,'centerAttempt'=>true]);$d=perform_action($runtime,$id,['action'=>'reveal']);$d=perform_action($runtime,$id,['action'=>'result','correct'=>false]);ok_rule($d['state']['currentPlayerId']==='J2','failed center question rotates turn');ok_rule($d['marker'][0]['atCenter']===true,'player remains physically at center after miss');$d=perform_action($runtime,$id,['action'=>'draw','categoryId'=>$categoryId]);$d=perform_action($runtime,$id,['action'=>'reveal']);$d=perform_action($runtime,$id,['action'=>'result','correct'=>false]);ok_rule($d['state']['currentPlayerId']==='J1'&&$d['state']['centerReadyPlayerId']==='J1','returning turn reactivates center question');$d=perform_action($runtime,$id,['action'=>'draw','categoryId'=>$categoryId,'centerAttempt'=>true]);$d=perform_action($runtime,$id,['action'=>'reveal']);$d=perform_action($runtime,$id,['action'=>'result','correct'=>true]);ok_rule($d['state']['status']==='closed'&&($d['state']['close']['reason']??null)==='victoria_centro','only correct center answer wins');echo "All game-rule tests passed.\n";
